import{_ as i,o as a,c as t,a2 as n}from"./chunks/framework.CqGPl1zp.js";const e="/newx-doc/assets/%E4%BC%9A%E8%AF%9D%E8%81%8A%E5%A4%A9.CFop-jZk.png",h="/newx-doc/assets/%E5%8F%B3%E9%94%AE%E8%8F%9C%E5%8D%95.CAz_-fPN.png",l="/newx-doc/assets/%E7%A7%81%E8%81%8A%E5%B7%B2%E8%AF%BB.DZ_-LUtt.png",k="/newx-doc/assets/%E7%BE%A4%E6%B6%88%E6%81%AF%E5%B7%B2%E8%AF%BB.xWYKUZD8.png",y=JSON.parse('{"title":"【消息】私聊、群聊、频道消息","description":"","frontmatter":{},"headers":[],"relativePath":"im/message.md","filePath":"im/message.md","lastUpdated":null}'),p={name:"im/message.md"};function d(r,s,E,g,o,c){return a(),t("div",null,[...s[0]||(s[0]=[n('<h1 id="【消息】私聊、群聊、频道消息" tabindex="-1">【消息】私聊、群聊、频道消息 <a class="header-anchor" href="#【消息】私聊、群聊、频道消息" aria-label="Permalink to &quot;【消息】私聊、群聊、频道消息&quot;">​</a></h1><p>消息是 IM 的核心。消息模块由 <code>yudao-module-im</code> 后端模块的 <code>message</code> 包实现，用户侧前端在 <code>@/views/im/home</code> 的聊天工作台。</p><p>按会话类型（枚举 ImConversationTypeEnum：1=私聊，2=群聊，3=频道）分为三张消息表，外加一张记录「已读位点」的会话已读表：</p><ul><li><strong>私聊消息</strong>：一对一聊天，落 <code>im_private_message</code>。</li><li><strong>群聊消息</strong>：群里聊天，落 <code>im_group_message</code>，支持 @ 成员、定向可见。</li><li><strong>频道消息</strong>：运营向订阅者推送的图文素材，落 <code>im_channel_message</code>（详见 <a href="./channel">《频道》</a>）。</li><li><strong>会话已读</strong>：每个用户在每个会话里「已读到第几条」，落 <code>im_conversation_read</code>，是未读数与已读回执的基础。</li></ul><p>本篇与《WebSocket》篇的分工</p><p>本篇讲消息「是什么、怎么发、怎么撤回、怎么算已读」；消息「怎么实时推到对端、断线后怎么补」属于通道层，统一在 <a href="./websocket">《WebSocket 实时推送与离线消息》</a> 讲，本篇用 <code>详见</code> 引过去，不重复。</p><h2 id="_1-消息类型" tabindex="-1">1. 消息类型 <a class="header-anchor" href="#_1-消息类型" aria-label="Permalink to &quot;1. 消息类型&quot;">​</a></h2><p>消息类型由枚举 ImContentTypeEnum 定义，消息表的 <code>type</code> 字段存的就是它的整数值（如 101=文本、102=图片）。每个类型带两个关键标志：</p><ul><li><code>persistent</code>（是否入库）：<code>true</code> 落消息表、离线 <code>pull</code> 能拉到；<code>false</code> 仅 WebSocket 在线推、离线丢弃。</li><li><code>normal</code>（是否聊天消息）：<code>true</code> 是用户主动发的聊天消息、计入会话未读数，也是用户发送入口唯一允许的类型；<code>false</code> 是系统事件 / 信号。</li></ul><p><strong>用户能主动发送</strong>的聊天消息（<code>normal=true</code>），<code>content</code> 字段就是对应消息体类序列化成的 JSON：</p><table tabindex="0"><thead><tr><th>值</th><th>类型</th><th>消息体类</th><th>说明</th></tr></thead><tbody><tr><td>101</td><td>文本</td><td>TextMessage</td><td>纯文本；Unicode emoji 也走文本</td></tr><tr><td>102</td><td>图片</td><td>ImageMessage</td><td></td></tr><tr><td>103</td><td>语音</td><td>AudioMessage</td><td></td></tr><tr><td>104</td><td>视频</td><td>VideoMessage</td><td></td></tr><tr><td>105</td><td>文件</td><td>FileMessage</td><td></td></tr><tr><td>115</td><td>表情</td><td>FaceMessage</td><td>表情贴图，来自系统 / 用户表情包（详见 <a href="./face">《内容》</a>）</td></tr><tr><td>108</td><td>名片</td><td>CardMessage</td><td>把用户 / 群名片推荐给其他会话</td></tr><tr><td>107</td><td>合并转发</td><td>MergeMessage</td><td>多条消息合并成一条「聊天记录」</td></tr><tr><td>125</td><td>素材</td><td>MaterialMessage</td><td>频道推送的图文卡片（详见 <a href="./channel">《频道》</a>）</td></tr></tbody></table><p>除聊天消息外，还有一类<strong>系统事件消息</strong>（<code>normal=false</code>，用户不能直接发、由系统产生）：撤回、已读、回执，以及好友 / 群 / 通话等通知。它们<strong>是否入库分两种</strong>：</p><ul><li><strong>入库</strong>（<code>persistent=true</code>）：作为聊天里的提示渲染、离线也能拉到。例如：新增好友 FRIEND_ADD（渲染「你们已经是好友了」气泡）、群事件 GROUP_CREATE / GROUP_MEMBER_INVITE / GROUP_MEMBER_QUIT（群创建、成员变动提示）、通话开始 / 结束 RTC_CALL_START / RTC_CALL_END、撤回 RECALL。</li><li><strong>不入库</strong>（<code>persistent=false</code>）：纯信令 / 瞬时态，离线即丢弃。例如：已读 READ、回执 RECEIPT、通话邀请 RTC_CALL、参与者加入 / 离开 RTC_PARTICIPANT_CONNECTED / RTC_PARTICIPANT_DISCONNECTED、正在输入。</li></ul><p>各类通知的推送范围与入库策略详见 <a href="./websocket">《WebSocket 实时推送与离线消息》</a>。</p><h2 id="_2-表结构" tabindex="-1">2. 表结构 <a class="header-anchor" href="#_2-表结构" aria-label="Permalink to &quot;2. 表结构&quot;">​</a></h2><blockquote><p>省略 creator/create_time/updater/update_time/deleted/tenant_id 等通用字段</p></blockquote><h3 id="_2-1-私聊消息" tabindex="-1">2.1 私聊消息 <a class="header-anchor" href="#_2-1-私聊消息" aria-label="Permalink to &quot;2.1 私聊消息&quot;">​</a></h3><p>私聊消息，由 ImPrivateMessageController 提供接口（<code>/im/message/private</code>）。</p><div class="language-SQL vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> `</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">im_private_message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">` (</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AUTO_INCREMENT COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `client_message_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;客户端消息编号，用于发送幂等&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `sender_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;发送人编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `receiver_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;接收人编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `type`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> smallint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;消息类型&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `content`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> text</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;消息内容，JSON 格式&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `status`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> tinyint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;消息状态（0=正常，2=已撤回）&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `receipt_status`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> tinyint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;回执状态（0=不需要，1=待完成，2=已完成）&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `send_time`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> datetime</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;发送时间&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  UNIQUE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `uk_im_private_sender_client_msg`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`sender_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`client_message_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ENGINE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">InnoDB COMMENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;IM 私聊消息表&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>① <code>client_message_id</code> 客户端生成的消息编号，<strong>发送时由客户端生成</strong>，配合唯一键 <code>(sender_id, client_message_id)</code> 做发送幂等（同一条重发不会落两条，见 <a href="#_3-3-顺序性与唯一性">§3.3</a>）。</p><p>② <code>type</code> 消息类型（见 <a href="#_1-消息类型">§1</a>）；<code>content</code> 消息内容，统一存 JSON 文本，按 <code>type</code> 反序列化为对应结构（文本 / 图片 / 文件 …）。</p><p>③ <code>status</code> 消息状态（枚举 ImMessageStatusEnum：0=正常，2=已撤回；另有 -1=发送中，仅客户端用）；<code>receipt_status</code> 回执状态（枚举 ImMessageReceiptStatusEnum），<strong>对方已读时回写</strong>（见 <a href="#_4-已读回执">§4</a>）。</p><h3 id="_2-2-群聊消息" tabindex="-1">2.2 群聊消息 <a class="header-anchor" href="#_2-2-群聊消息" aria-label="Permalink to &quot;2.2 群聊消息&quot;">​</a></h3><p>群聊消息，由 ImGroupMessageController 提供接口（<code>/im/message/group</code>）。结构与私聊基本一致，把「接收人」换成「群」，并多了定向可见与 @ 两个字段：</p><div class="language-SQL vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> `</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">im_group_message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">` (</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AUTO_INCREMENT COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `client_message_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;客户端消息编号，用于发送幂等&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `sender_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;发送人编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `group_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;群编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `type`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> smallint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;消息类型&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `content`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> text</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;消息内容，JSON 格式&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `receiver_user_ids`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;可见成员编号快照，逗号分隔；发送时固化当时全部可见成员&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `at_user_ids`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@目标用户编号列表，逗号分隔&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `status`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> tinyint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;消息状态（0=正常，2=已撤回）&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `receipt_status`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> tinyint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;回执状态&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `send_time`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> datetime</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;发送时间&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  UNIQUE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `uk_im_group_sender_client_msg`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`sender_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`client_message_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ENGINE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">InnoDB COMMENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;IM 群聊消息表&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>① <code>receiver_user_ids</code> 是<strong>发送当时的可见成员快照</strong>：群消息发送时，把当时全部可见成员的 id 逗号拼接存进来（<strong>不是留空表示全员</strong>），定向消息则存指定的接收人子集。pull 时用 <code>FIND_IN_SET(:userId, receiver_user_ids)</code> 判断当前用户能否看到这条消息。</p><p>为什么存全量可见成员快照，而不是留空或另建「用户 - 消息」索引表？</p><p><strong>本质是用一行的宽度，换掉用户级消息索引的写放大、以及「成员历史区间」JOIN 的复杂度</strong>——发一条群消息只写一行，可见性在落库那刻就定死，pull 一个 <code>FIND_IN_SET</code> 即可过滤；信任 MySQL 的能力，不把系统搞复杂。代价是行宽随群成员数增长，对当前规模可接受（机制详见 <a href="./websocket#_4-1-消息增量拉取">《WebSocket》§4.1</a>）。</p><p>② <code>at_user_ids</code> 被 @ 的成员编号列表，前端据此高亮提醒；@ 用对方真实昵称（<code>nickname</code>）。</p><h3 id="_2-3-频道消息" tabindex="-1">2.3 频道消息 <a class="header-anchor" href="#_2-3-频道消息" aria-label="Permalink to &quot;2.3 频道消息&quot;">​</a></h3><p>频道消息，由 ImChannelMessageController 提供接口（<code>/im/channel/message</code>）。它是运营推送素材时生成的快照，用户侧只拉取与已读，不发送（运营侧推送详见 <a href="./channel">《频道》</a>）。</p><div class="language-SQL vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> `</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">im_channel_message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">` (</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AUTO_INCREMENT COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `channel_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;频道编号（冗余便于检索）&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `material_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;关联素材编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `type`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> smallint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;消息类型&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `content`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8192</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DEFAULT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;消息内容；推送 payload JSON 快照&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `receiver_user_ids`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> text</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;接收人编号列表，逗号分隔；为空表示全员&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `send_time`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> datetime</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;发送时间&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ENGINE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">InnoDB COMMENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;IM 频道消息表&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>① <code>content</code> 是推送时的图文卡片快照（标题 / 封面 / 摘要 / 链接），正文富文本不在此存（在素材表 <code>im_channel_material</code>）。</p><p>② <code>receiver_user_ids</code> 接收人范围。注意它和群聊语义<strong>相反</strong>：<strong>为空表示全员推送</strong>（推给全部订阅者），非空才是定向给指定用户。频道是「运营 → 订阅者」的单向广播，没有群聊那种「成员可见性快照」问题，所以保留「空 = 全员」的简单语义。</p><h3 id="_2-4-会话已读" tabindex="-1">2.4 会话已读 <a class="header-anchor" href="#_2-4-会话已读" aria-label="Permalink to &quot;2.4 会话已读&quot;">​</a></h3><p>会话已读，记录每个用户在每个会话里「已读到的最大消息编号」，是计算未读数与判断已读回执的依据。</p><div class="language-SQL vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> `</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">im_conversation_read</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">` (</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AUTO_INCREMENT COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `user_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;用户编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `conversation_type`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> tinyint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;会话类型（1=私聊，2=群聊，3=频道）&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `target_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;目标编号：私聊=对端用户，群聊=群，频道=频道&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `message_id`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bigint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;最大已读消息编号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  `read_time`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> datetime</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMENT </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;最近已读时间&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  UNIQUE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `uk_im_conversation_read_user_target`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`user_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`conversation_type`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`target_id`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ENGINE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">InnoDB COMMENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;IM 会话已读表&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>① <code>(user_id, conversation_type, target_id)</code> 定位一条会话已读记录：<code>conversation_type</code> 用枚举 ImConversationTypeEnum（1=私聊，2=群聊，3=频道），<code>target_id</code> 随类型变化——私聊是对端用户编号、群聊是群编号、频道是频道编号。</p><p>② <code>message_id</code> 是「已读位点」——位点之后的消息即未读。用「位点」而非「逐条标记」，让未读计算与已读上报都很轻量。</p><h2 id="_3-发送、撤回与拉取" tabindex="-1">3. 发送、撤回与拉取 <a class="header-anchor" href="#_3-发送、撤回与拉取" aria-label="Permalink to &quot;3. 发送、撤回与拉取&quot;">​</a></h2><h3 id="_3-1-发送主流程" tabindex="-1">3.1 发送主流程 <a class="header-anchor" href="#_3-1-发送主流程" aria-label="Permalink to &quot;3.1 发送主流程&quot;">​</a></h3><p>三类消息发送共用一套主流程（私聊 <code>sendPrivateMessage</code>、群聊 <code>sendGroupMessage</code>）：</p><ol><li><strong>校验</strong>：校验会话关系（私聊校验好友 / 拉黑，见 <a href="./friend">《好友》</a>；群聊校验成员 / 禁言）、敏感词（见 <a href="./face">《内容》</a>）。</li><li><strong>落库</strong>：写入对应消息表，<code>id</code> 由服务端自增、<code>client_message_id</code> 由客户端带入做幂等。</li><li><strong>推送</strong>：通过 WebSocket 推给接收方（及发送方其它端），详见 <a href="./websocket">《WebSocket》</a>。</li><li><strong>拉取</strong>：接收方在线即时收到；离线时下次通过 <code>pull</code> 接口按 <code>minId</code> 游标增量补齐。</li></ol><p>三类消息的差异：</p><table tabindex="0"><thead><tr><th>维度</th><th>私聊</th><th>群聊</th><th>频道</th></tr></thead><tbody><tr><td>接收范围</td><td>对端一人</td><td>全群 / 定向（<code>receiver_user_ids</code>）</td><td>订阅者 / 定向</td></tr><tr><td>谁能发</td><td>互为好友的用户</td><td>群成员（未被禁言）</td><td>仅运营推送</td></tr><tr><td>特有能力</td><td>—</td><td>@ 成员、定向可见</td><td>图文素材卡片</td></tr></tbody></table><h3 id="_3-2-撤回" tabindex="-1">3.2 撤回 <a class="header-anchor" href="#_3-2-撤回" aria-label="Permalink to &quot;3.2 撤回&quot;">​</a></h3><p>撤回把消息状态置为「已撤回」，对端的气泡替换为「xxx 撤回了一条消息」提示。消息状态枚举 ImMessageStatusEnum：</p><table tabindex="0"><thead><tr><th>状态值</th><th>枚举</th><th>说明</th><th>可执行操作</th></tr></thead><tbody><tr><td>0</td><td>NORMAL</td><td>正常</td><td>撤回（本人默认 5 分钟内；群主 / 管理员撤违规消息不限时）、引用、转发</td></tr><tr><td>2</td><td>RECALL</td><td>已撤回</td><td>—</td></tr></tbody></table><p>撤回说明</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发送 ──→ 正常(0) ──撤回（本人默认 5 分钟内；群主 / 管理员不限时）──→ 已撤回(2)（终态）</span></span></code></pre></div><ul><li><strong>发送</strong>（<code>sendPrivateMessage</code> / <code>sendGroupMessage</code>）：消息落库，初始状态正常。</li><li><strong>撤回</strong>（<code>recallPrivateMessage</code> / <code>recallGroupMessage</code>）：本人可在<strong>默认 5 分钟内</strong>（<code>yudao.im.message.recall-timeout-minutes</code>）撤回自己的消息；<strong>群主 / 管理员可撤回成员的违规消息、不受时间限制</strong>。撤回后把 <code>status</code> 置为已撤回并推送；前端渲染居中灰字提示。撤回是终态，不可恢复。</li></ul><p><code>-1=发送中</code> 是纯客户端态（消息尚未拿到服务端响应），不落库。</p><h3 id="_3-3-顺序性与唯一性" tabindex="-1">3.3 顺序性与唯一性 <a class="header-anchor" href="#_3-3-顺序性与唯一性" aria-label="Permalink to &quot;3.3 顺序性与唯一性&quot;">​</a></h3><p>① <strong>顺序性</strong>：按服务端自增主键 <code>id</code> 定序，不依赖客户端时间（各端时钟可能不准）。</p><p>② <strong>唯一性</strong>：靠客户端生成的 <code>client_message_id</code>（每条消息一个 UUID）+ 唯一键 <code>(sender_id, client_message_id)</code> 去重，弱网重发同一条不会落两条。</p><p>二者的实现与离线补偿机制由通道层统一保证，本篇不展开，详见 <a href="./websocket#_4-在线推-离线拉">《WebSocket 实时推送与离线消息》§4</a>。</p><h2 id="_4-已读回执" tabindex="-1">4. 已读回执 <a class="header-anchor" href="#_4-已读回执" aria-label="Permalink to &quot;4. 已读回执&quot;">​</a></h2><p>已读由两部分配合：消息表的 <code>receipt_status</code>（这条消息是否被读）+ 会话已读表 <code>im_conversation_read</code> 的已读位点（读到第几条）。</p><ul><li><strong>上报已读</strong>：进入会话或滚动到底时，调用 <code>readPrivateMessages</code> / <code>readGroupMessages</code> / <code>readChannelMessages</code> 上报「已读到的最大消息编号」、更新 <code>im_conversation_read</code>；私聊 / 群聊随后向发送方推回执（RECEIPT），频道只推 READ 同步本人多端、不推回执（单向广播无「谁已读」）。</li><li><strong>私聊</strong>：发送方在自己的消息气泡尾部看到「已读 / 未读」；多端 / 重连后用 <code>getMaxReadMessageId</code> 补齐对方已读位点。</li><li><strong>群聊</strong>：发送方看到「N 人已读」，点击可用 <code>getGroupReadUserIds</code> 查看已读 / 未读成员名单。</li><li><strong>频道</strong>：也记已读位点（<code>conversation_type=3</code>）用于算未读红点，但频道是单向广播，不展示「谁已读」。</li></ul><p>已读回执开关</p><p>私聊 / 群聊的已读回执可分别由配置项 <code>yudao.im.message.private-read-enabled</code>、<code>yudao.im.message.group-read-enabled</code>（<strong>默认都开</strong>）控制；关闭后对应 <code>read</code> 接口直接报错、服务端不再下发 READ / RECEIPT 信号（适合不想暴露「已读」的场景）。</p><h2 id="_5-用户侧-ui" tabindex="-1">5. 用户侧 UI <a class="header-anchor" href="#_5-用户侧-ui" aria-label="Permalink to &quot;5. 用户侧 UI&quot;">​</a></h2><p>对应 [IM 即时通讯 -&gt; 聊天] 工作台，对应 <code>@/views/im/home/pages/conversation</code> 目录。左侧会话列表（<code>ConversationItem.vue</code>，展示最后一条预览、未读红点、免打扰小点、草稿标记），右侧消息面板（<code>MessagePanel.vue</code>）。</p><p><img src="'+e+'" alt="会话与消息"></p><p>底部输入区（<code>MessageInput.vue</code>）的工具栏依次是表情、图片、文件、语音、视频；文本框支持 Enter 发送、Shift+Enter 换行。群聊里输入 <code>@</code> 弹出成员选择（<code>MentionPicker.vue</code>），可 @ 某人或 @全体成员。</p><p>不同消息类型由 <code>MessageBubble.vue</code> 按 <code>type</code> 分发渲染（文本 / 图片 / 语音 / 视频 / 文件 / 表情 / 名片 / 合并转发 / 素材卡片）。</p><p>在消息上右键打开操作菜单（<code>ContextMenu.vue</code>）：撤回（本人 5 分钟内，群主 / 管理员可撤成员消息）、引用回复、转发、多选、复制、添加到表情、群消息置顶（群主 / 管理员）等。</p><p><img src="'+h+'" alt="消息右键菜单"></p><p>私聊里自己发的消息尾部显示「已读 / 未读」；群聊里自己发的消息可点尾部「N 人已读」查看已读 / 未读成员名单。</p><p><img src="'+l+'" alt="私聊已读"></p><p><img src="'+k+'" alt="群消息已读"></p><h2 id="_6-运营侧" tabindex="-1">6. 运营侧 <a class="header-anchor" href="#_6-运营侧" aria-label="Permalink to &quot;6. 运营侧&quot;">​</a></h2><p>运营侧在 [IM 即时通讯 -&gt; 私聊管理 / 群聊管理 / 频道管理] 下，分别由 ImPrivateMessageManagerController、ImGroupMessageManagerController、ImChannelMessageManagerController 提供<strong>只读分页查询</strong>，用于排查会话内容；不提供代发 / 修改。三类消息管理页结构一致（发送人 / 接收方 / 类型 / 内容预览 / 时间），频道消息的推送另见 <a href="./channel">《频道》</a>：</p><table tabindex="0"><thead><tr><th>私聊消息</th><th>群聊消息</th><th>频道消息</th></tr></thead><tbody><tr><td>私聊消息</td><td>群聊消息</td><td>频道消息</td></tr></tbody></table><h2 id="_7-容量与未来扩展" tabindex="-1">7. 容量与未来扩展 <a class="header-anchor" href="#_7-容量与未来扩展" aria-label="Permalink to &quot;7. 容量与未来扩展&quot;">​</a></h2><p>私聊 / 群聊 / 频道三张消息表都是<strong>单份存储</strong>——每条消息只落一行，可见性靠群消息的 <code>receiver_user_ids</code> 快照过滤（见前文 §2），不为每个接收人再写一份消息索引。所以消息体按「消息条数」增长、而非按「消息 × 接收人」放大，单表经验上控制在 <strong>5000 万行</strong> 量级，到顶再考虑归档 / 分表。</p><p>拉取窗口（控制离线补偿成本）</p><p>客户端<strong>不全量回放历史</strong>：<code>pull</code> 只返回「离线增量 + 最近 N 天」，更早的历史靠本地 IndexedDB 缓存或历史接口按需倒翻。N 天由配置项 <code>yudao.im.message.private-pull-max-days</code> / <code>group-pull-max-days</code>（默认 <strong>30</strong> 天）控制；单次拉取按 <code>minId</code> 游标分页，<code>size</code> 受接口上限与服务端 <code>max-pull-size</code>（默认 1000）约束，不会一次拉海量。群消息因 <code>receiver_user_ids</code> 行宽随成员数增长，是容量上要额外关注的点。</p><p>规模上来后可循序演进：</p><ol><li><strong>冷数据归档</strong>：超过窗口的老消息迁出主表，主表只留热数据。</li><li><strong>分库分表</strong>：消息表水平拆分扩容（如 4 / 8 / 16 表线性放大总容量）。</li></ol>',80)])])}const _=i(p,[["render",d]]);export{y as __pageData,_ as default};
